<a class="btn btn-outline-secondary mb-3" href="<?= BASE_URL ?>/reservations">Volver a reservas</a><h1 class="h3 mb-4">Reserva #<?= (int)$row['id'] ?></h1>
<?php if ($closing): ?><div class="alert alert-info">Operación cerrada. <a href="<?= BASE_URL ?>/closings/show?id=<?= (int)$closing['id'] ?>">Ver detalle del cierre</a></div><?php elseif ($row['estado_reserva']==='aprobada' && in_array($user['rol'],['superadmin','admin'],true)): ?><a class="btn btn-success mb-4" href="<?= BASE_URL ?>/closings/create?reserva_id=<?= (int)$row['id'] ?>">Registrar cierre de operación</a><?php endif; ?>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?><?php if ($errors): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="card card-body mb-4"><dl class="row mb-0"><?php foreach (['cliente'=>'Cliente','titulo'=>'Inmueble','vendedor'=>'Vendedor','created_at'=>'Registrada','aprobador'=>'Aprobada por'] as $key=>$label): ?><dt class="col-sm-4"><?= e($label) ?></dt><dd class="col-sm-8"><?= e($row[$key] ?? '—') ?></dd><?php endforeach; ?><dt class="col-sm-4">Monto</dt><dd class="col-sm-8"><?= e($row['moneda']) ?> <?= number_format((float)$row['monto_reserva'],0) ?></dd><dt class="col-sm-4">Estado</dt><dd class="col-sm-8"><?= e(Reservation::STATES[$row['estado_reserva']]) ?></dd></dl></div>
<?php $admin=in_array($user['rol'],['superadmin','admin'],true); $actions=$row['estado_reserva']==='pendiente' ? ($admin ? ['aprobada','rechazada','cancelada'] : ['cancelada']) : ($row['estado_reserva']==='aprobada' && $admin ? ['cancelada'] : []); ?>
<?php if ($actions): ?><form id="modificar-estado" class="card card-body" method="post" action="<?= BASE_URL ?>/reservations/transition?id=<?= (int)$row['id'] ?>" onsubmit="return confirm('¿Confirmas el cambio de estado de esta reserva?')"><?= Csrf::field() ?><h2 class="h5">Modificar estado de la reserva</h2><p>Si necesitas eliminar el inmueble del listado, cancela primero su reserva aprobada y después vuelve a Propiedades.</p><label class="form-label" for="accion">Acción</label><select class="form-select mb-3" id="accion" name="accion" required><option value="">Seleccionar</option><?php foreach ($actions as $value): ?><option value="<?= e($value) ?>"><?= e(['aprobada'=>'Aprobar','rechazada'=>'Rechazar','cancelada'=>'Cancelar'][$value]) ?></option><?php endforeach; ?></select><label class="form-label" for="motivo">Motivo / observación *</label><textarea class="form-control mb-3" id="motivo" name="motivo" maxlength="2000" rows="3" required></textarea><p class="small text-muted">Aprobar marca el inmueble como reservado. Cancelar una reserva aprobada libera el inmueble si aún figura reservado. La operación queda en el historial del CRM.</p><button class="btn btn-primary align-self-start">Aplicar cambio</button></form><?php else: ?><section id="modificar-estado" class="card card-body"><h2 class="h5">Modificar estado de la reserva</h2><p class="mb-0"><?php if ($row['estado_reserva']==='aprobada'): ?>Solo un administrador puede cancelar una reserva aprobada.<?php else: ?>Esta reserva está finalizada. Su estado no admite cambios y se conserva su historial.<?php endif; ?></p></section><?php endif; ?>

<a class="btn btn-outline-secondary mt-3" href="<?= BASE_URL ?>/properties">Volver a Propiedades</a>
